// Native pages for two engine plugins: the Kanban board (agents pick up "ready" tasks) and Achievements.
// Which board this browser shows (empty: the engine's current one). Filters live for the visit, seeded once from the engine's board settings.
const kbSlug=()=>store.get('kb-board','')||'';
const KB=(p,o)=>{const b=kbSlug();return H('/plugins/kanban'+p+(b?(p.includes('?')?'&':'?')+'board='+encodeURIComponent(b):''),o)};
const KF={q:'',tenant:'',agent:'',archived:false,lanes:true,seeded:false,warnOff:false,warnOpen:false};
const KSel=new Set();const KFail=new Map();let KSelLast=null;
const KCOLS=[['triage','Triage','New ideas to sort out'],['todo','To do','Planned, not ready yet'],['scheduled','Scheduled','Waiting for their time'],['ready','Ready','An agent picks these up'],['running','Running','An agent moves tasks here when it starts'],['blocked','Blocked','Needs something first'],['review','Review','Check the result'],['done','Done','Finished'],['archived','Archived','Put away, not deleted']];
const kAge=t=>{const s=t.age?.created_age_seconds??t.created_age_seconds??(t.created_at?Date.now()/1000-t.created_at:null);return s==null?'':s<3600?Math.max(1,Math.round(s/60))+' min':s<86400?Math.round(s/3600)+' h':Math.round(s/86400)+' d'};
// how long a task may sit in a column before its card is outlined amber, then red (the engine's thresholds)
const KSTALE={ready:[3600,86400],running:[600,3600],blocked:[3600,86400],todo:[604800,2592000]};
const kbStale=t=>{const l=KSTALE[t.status],s=t.status==='running'?t.age?.started_age_seconds:t.age?.created_age_seconds;return !l||s==null?'':s>=l[1]?'stale-r':s>=l[0]?'stale-a':''};
const kbPlain=s=>String(s??'').replace(/\bHermes\b/g,'the engine').replace(/\bhermes\b/g,'engine');
const kbMd=s=>Pages._kbCfg?.render_markdown===false?`<div class="kd-plain">${esc(kbPlain(s))}</div>`:`<div class="md kd-md">${md(kbPlain(s))}</div>`;
const kbSize=n=>!n?'0 B':n<1024?n+' B':n<1048576?Math.round(n/1024)+' KB':(n/1048576).toFixed(1)+' MB';
const kbHum=s=>{s=String(s||'').replace(/_/g,' ');return s.charAt(0).toUpperCase()+s.slice(1)};
const kbSevWord={warning:'Needs a look',error:'Problem',critical:'Serious problem'};
const kbAll=()=>(Pages._kb?.columns||[]).flatMap(c=>c.tasks||[]);
const kbMeta=()=>{const s=kbSlug()||Pages._kbCur||'default';return (Pages._kbBoards||[]).find(b=>b.slug===s)||null};
// the board picker's label: its name, and the project it belongs to (quieter)
const kbPickLabel=m=>esc((m.icon?m.icon+' ':'')+(m.name||m.slug))+(m.project_name?`<small class="kbproj">${esc(m.project_name)}</small>`:'');
const kbEl=()=>route().page?.id==='kanban'?Pages._kbEl:null;
const kbRefresh=()=>{const el=kbEl();if(el?.isConnected)kbLoad(el).catch(fail);kbBoards()};
function kbFilter(t){const q=KF.q.trim().toLowerCase();if(KF.agent&&(KF.agent==='-'?t.assignee:t.assignee!==KF.agent))return false;if(KF.tenant&&t.tenant!==KF.tenant)return false;
 return !q||`${t.id} ${t.title||''} ${t.body||''} ${t.result||''} ${t.latest_summary||''} ${t.assignee||''} ${t.tenant||''}`.toLowerCase().includes(q)}

PAGES.kanban=async(p,el)=>{Pages._kbEl=el;const gone=pageTok(el);
 setActions(`<button data-act="kb-boards" aria-haspopup="menu" title="Switch boards">${icon('layers',16)}<span id="kbPickN">${kbMeta()?kbPickLabel(kbMeta()):'Board'}</span>${icon('chevD',14)}</button><button data-act="kb-dispatch" title="Agents check for Ready tasks every minute. This asks them now.">${icon('play',16)}Start ready tasks</button><button data-act="kb-refresh">${icon('refresh',16)}Refresh</button><button class="primary" data-act="kb-new">${icon('plus',16)}New task</button>`);
 if(!Pages._kbCfg){const c=await KB('/config').catch(()=>null);Pages._kbCfg=c||{};if(!KF.seeded){KF.seeded=true;KF.tenant=c?.default_tenant||'';KF.lanes=c?.lane_by_profile!==false;KF.archived=!!c?.include_archived_by_default}if(gone())return}
 KB('/orchestration').then(o=>{Pages._kbOrch=o;kbTool(el)}).catch(()=>{});kbBoards();
 await kbLoad(el);if(gone())return;kbLive();
 // without the live stream (or when it drops) look again every 10 s; a drag in progress is never redrawn under the pointer
 const tick=()=>{if(route().page?.id!=='kanban')return;if(document.hidden||Pages._kbWsOn||Pages._kbDrag){Pages._kbT=setTimeout(tick,10000);return}kbLoad(el).then(()=>kbDrawerLive()).catch(()=>{}).finally(()=>{clearTimeout(Pages._kbT);Pages._kbT=setTimeout(tick,10000)})};
 clearTimeout(Pages._kbT);Pages._kbT=setTimeout(tick,10000);
};
async function kbBoards(){try{const r=await KB('/boards');Pages._kbBoards=r.boards||[];Pages._kbCur=r.current||'default';
 if(kbSlug()&&kbSlug()!=='default'&&!Pages._kbBoards.some(b=>b.slug===kbSlug())){store.set('kb-board','');toast('That board was archived. Showing the main board.');kbRefresh()}
 const n=$('#kbPickN'),m=kbMeta();if(n&&m)n.innerHTML=kbPickLabel(m)}catch{}}
// the newest load wins: an older answer arriving late (a slow poll after a filter change) is dropped
async function kbLoad(el){const g=Pages._kbGen=(Pages._kbGen||0)+1;const b=await KB('/board'+qp({tenant:KF.tenant||undefined,include_archived:KF.archived?'true':undefined}));if(g!==Pages._kbGen)return;
 const sig=JSON.stringify(b.columns)+'|'+(b.assignees||[]).join()+'|'+(b.tenants||[]).join();const same=Pages._kbSig===sig&&el.querySelector('#kbArea .kboard');Pages._kb=b;Pages._kbSig=sig;if(!el.isConnected)return;
 if(!el.querySelector('#kbArea'))kbFrame(el);kbTool(el);if(!same&&!Pages._kbDrag)kbPaint(el)}
function kbFrame(el){el.innerHTML=`<div class="toolbar ktool"><div class="search">${icon('search',16)}<input id="kbQ" type="search" placeholder="Search tasks" aria-label="Search tasks" value="${esc(KF.q)}"></div><div class="ktool-r" id="kbToolR"></div></div><div id="kbWarn"></div><div id="kbArea"></div><div class="kfoot"><div class="ktrash" id="kbTrash" aria-hidden="true">${icon('trash',16)}Drop here to delete</div><div id="kbBulk"></div></div>`;
 let qt;el.querySelector('#kbQ').oninput=e=>{clearTimeout(qt);qt=setTimeout(()=>{KF.q=e.target.value;kbPaint(el);kbTool(el)},120)};
 kbPan(el.querySelector('#kbArea'));kbTouch(el.querySelector('#kbArea'))}
// filters and board settings next to the search; drawn again only when what they show changes
function kbTool(el){const r=el.querySelector('#kbToolR');if(!r)return;const b=Pages._kb||{},o=Pages._kbOrch,ag=b.assignees||[],tn=b.tenants||[];const any=KF.q||KF.agent||KF.tenant||KF.archived;
 const sig=JSON.stringify([ag,tn,o?.auto_decompose,KF.agent,KF.tenant,KF.archived,KF.lanes,!!any]);if(r._sig===sig)return;r._sig=sig;
 r.innerHTML=`<select id="kbAgS" style="width:auto" aria-label="Show tasks of"><option value="">Every agent</option><option value="-" ${KF.agent==='-'?'selected':''}>Nobody yet</option>${ag.map(n=>`<option value="${esc(n)}" ${KF.agent===n?'selected':''}>${esc(ident(n).name)}</option>`).join('')}</select>
  ${tn.length?`<select id="kbTnS" style="width:auto" aria-label="Group"><option value="">Every group</option>${tn.map(n=>`<option value="${esc(n)}" ${KF.tenant===n?'selected':''}>${esc(n)}</option>`).join('')}</select>`:''}
  <label class="ktg">${toggle(KF.archived,'Show archived tasks','id="kbArT"')}<span>Archived</span></label><label class="ktg">${toggle(KF.lanes,'Group running tasks by agent','id="kbLnT"')}<span>By agent</span></label>
  ${any?`<button class="ghost small" id="kbClr">${icon('x',14)}Clear filters</button>`:''}${o?`<button class="chip kmode" data-act="kb-settings" title="Change in Board settings">New ideas: ${o.auto_decompose?'split automatically':'split by hand'}</button>`:''}`;
 r.querySelector('#kbAgS').onchange=e=>{KF.agent=e.target.value;kbPaint(el);kbTool(el)};
 const ts=r.querySelector('#kbTnS');if(ts)ts.onchange=e=>{KF.tenant=e.target.value;kbLoad(el).catch(fail);kbTool(el)};
 r.querySelector('#kbArT').onchange=e=>{KF.archived=e.target.checked;kbLoad(el).catch(fail)};r.querySelector('#kbLnT').onchange=e=>{KF.lanes=e.target.checked;kbPaint(el);kbTool(el)};
 const c=r.querySelector('#kbClr');if(c)c.onclick=()=>{const reload2=KF.tenant||KF.archived;Object.assign(KF,{q:'',agent:'',tenant:'',archived:false});const q=el.querySelector('#kbQ');if(q)q.value='';if(reload2)kbLoad(el).catch(fail);else{kbPaint(el);kbTool(el)}}}
const kbCard=t=>{const sel=KSel.has(t.id),f=KFail.get(t.id),w=t.warnings,pr=t.progress,need=t.status==='ready'&&!t.assignee,lc=t.link_counts||{},links=(lc.parents||0)+(lc.children||0),stl=kbStale(t);
 return `<div class="kcard ${sel?'sel':''} ${f?'failed':''} ${stl}" draggable="true" data-act="kb-open" data-id="${esc(t.id)}" tabindex="0" ${stl?`title="${stl==='stale-r'?'Waiting much longer than usual':'Waiting longer than usual'}"`:''}>
 <div class="ktop"><input type="checkbox" class="kchk" data-act="kb-sel" data-id="${esc(t.id)}" ${sel?'checked':''} aria-label="Select this task"><button class="kid" data-act="kb-copyid" data-id="${esc(t.id)}" title="Copy the task number">#${esc(t.id)}</button>${w?.count?`<span class="ksev ${esc(w.highest_severity||'warning')}" title="${esc(kbSevWord[w.highest_severity]||'Needs a look')}: open the task to see what went wrong">${icon('alert',12)}</span>`:''}${t.priority?`<span class="kpri ${t.priority>=2?'bad':t.priority>=1?'warn':''}" title="Priority ${t.priority}: higher is picked up first">P${t.priority}</span>`:''}</div>
 <b>${esc(t.title||'Untitled')}</b>${t.body?`<p>${esc(String(t.body).slice(0,140))}</p>`:''}
 ${pr?`<div class="kprog ${pr.done===pr.total?'full':''}" title="${pr.done} of ${pr.total} sub-tasks done"><s><i style="width:${Math.round(pr.done/Math.max(1,pr.total)*100)}%"></i></s><span>${pr.done}/${pr.total}</span></div>`:''}${f?`<p class="kerr">${esc(f)}</p>`:''}
 <div class="kmeta">${need?'<span class="chip warn" title="It is ready, but no agent picks it up until you choose one">Needs an agent</span>':t.assignee?`<span class="chip">${esc(ident(t.assignee).name)}</span>`:'<span class="chip">Unassigned</span>'}${t.tenant?`<span class="chip">${esc(t.tenant)}</span>`:''}${t.comment_count?`<span class="kcnt" title="${plural(t.comment_count,'comment')}">${icon('chat',12)}${t.comment_count}</span>`:''}${links?`<span class="kcnt" title="Waits for ${lc.parents||0}, ${lc.children||0} waiting for it">${icon('link',12)}${links}</span>`:''}<span class="kage">${kAge(t)}</span></div></div>`};
function kbPaint(el){const area=el.querySelector('#kbArea');if(!area)return;const b=Pages._kb||{columns:[]};const raw=Object.fromEntries((b.columns||[]).map(c=>[c.name,c.tasks||[]]));
 const ids=new Set(Object.values(raw).flat().map(t=>t.id));for(const id of [...KSel])if(!ids.has(id))KSel.delete(id);
 const byCol=Object.fromEntries(Object.entries(raw).map(([k,l])=>[k,l.filter(kbFilter)]));const total=ids.size;
 const k0=area.querySelector('.kboard'),sx=k0?.scrollLeft||0,cs=Object.fromEntries([...area.querySelectorAll('.kcol')].map(c=>[c.dataset.col,c.querySelector('.klist')?.scrollTop||0]));
 const lanes=list=>{const g={};for(const t of list)(g[t.assignee||'']||=[]).push(t);return Object.entries(g).map(([a,l])=>`<div class="klane"><div class="klane-h"><span>${esc(a?ident(a).name:'Nobody')}</span><span class="n">${l.length}</span></div>${l.map(kbCard).join('')}</div>`).join('')};
 const cols=KCOLS.filter(([id])=>id in byCol).map(([id,label,hint])=>{const l=byCol[id],shown=['todo','ready','running','done','archived'].includes(id)||raw[id].length;
  return `<section class="kcol ${shown?'':'kx'} ${id==='running'?'knodrop':''}" data-col="${id}"><header><b>${label}</b><span class="n">${l.length}</span><span class="kflex"></span>${l.length?`<button class="ghost icon kcolbtn" data-act="kb-selcol" data-col="${id}" title="Select every task here" aria-label="Select every task in ${label}">${icon('check',14)}</button>`:''}${['triage','todo','ready'].includes(id)?`<button class="ghost icon kcolbtn" data-act="kb-new" data-col="${id}" title="Add a task here" aria-label="Add a task to ${label}">${icon('plus',15)}</button>`:''}</header><p class="khint">${hint}</p><div class="klist">${id==='running'&&KF.lanes&&l.length?lanes(l):l.map(kbCard).join('')}${id==='archived'&&!l.length?'<p class="hint" style="margin:4px">Nothing archived.</p>':''}</div></section>`});
 area.innerHTML=`${total?'':`<div class="empty-hero" style="margin-bottom:16px"><b style="display:block;font-size:17px;margin-bottom:6px">Hand work to your agents</b><span style="color:var(--ink-2)">Add a task, give it to an agent and move it to Ready. The agent picks it up, works on it, and moves it along.</span></div>`}<div class="kboard ${KSel.size?'selecting':''}">${cols.join('')}</div>`;
 kbWarn(el);kbBulk(el);kbDrag(el);
 const fit=()=>{const k=el.querySelector('.kboard');if(!k)return;k.style.height=Math.max(320,innerHeight-k.getBoundingClientRect().top-18)+'px'};fit();window.removeEventListener('resize',Pages._kbFit||fit);Pages._kbFit=fit;window.addEventListener('resize',fit);
 {const k=area.querySelector('.kboard');if(k)k.scrollLeft=sx;area.querySelectorAll('.kcol').forEach(c=>{const l=c.querySelector('.klist');if(l&&cs[c.dataset.col])l.scrollTop=cs[c.dataset.col]})}}
// tasks the engine flags (stuck, failing, made-up references) in one strip above the board
function kbWarn(el){const box=el.querySelector('#kbWarn');if(!box)return;const list=kbAll().filter(t=>t.warnings?.count);if(KF.warnOff||!list.length){box.innerHTML='';return}
 const rank={warning:0,error:1,critical:2},top=list.reduce((m,t)=>rank[t.warnings.highest_severity]>rank[m]?t.warnings.highest_severity:m,'warning');
 box.innerHTML=`<div class="kwarn ${esc(top)}"><div class="kwarn-bar">${icon('alert',16)}<b>${list.length===1?'1 task needs attention':list.length+' tasks need attention'}</b><span class="kflex"></span><button class="ghost small" data-act="kb-warn-open">${KF.warnOpen?'Hide':'Show'}</button><button class="ghost icon" data-act="kb-warn-off" title="Hide until you reload the page" aria-label="Hide">${icon('x',15)}</button></div>
 <div class="kwarn-list ${KF.warnOpen?'open':''}"><div>${list.map(t=>`<div class="kwarn-row"><span class="ksev ${esc(t.warnings.highest_severity||'warning')}">${icon('alert',12)}</span><span class="t">${esc(t.title||'Untitled')}<small>${esc(t.assignee?ident(t.assignee).name:'Nobody')} · ${esc(Object.keys(t.warnings.kinds||{}).map(kbHum).join(', ')||kbSevWord[t.warnings.highest_severity]||'')}</small></span><button class="ghost small" data-act="kb-open" data-id="${esc(t.id)}">Open</button></div>`).join('')}</div></div></div>`}
ACT['kb-warn-open']=()=>{KF.warnOpen=!KF.warnOpen;const el=kbEl();if(!el)return;const l=el.querySelector('.kwarn-list'),b=el.querySelector('[data-act="kb-warn-open"]');l?.classList.toggle('open',KF.warnOpen);if(b)b.textContent=KF.warnOpen?'Hide':'Show'};
ACT['kb-warn-off']=()=>{KF.warnOff=true;const w=kbEl()?.querySelector('.kwarn');if(w){w.classList.add('closing');setTimeout(()=>kbWarn(kbEl()),220)}};

/* ---------- selecting several tasks ---------- */
function kbSelPaint(){const el=kbEl();if(!el)return;el.querySelectorAll('.kcard').forEach(c=>{const on=KSel.has(c.dataset.id);c.classList.toggle('sel',on);const x=c.querySelector('.kchk');if(x)x.checked=on});el.querySelector('.kboard')?.classList.toggle('selecting',!!KSel.size);kbBulk(el)}
const kbVisible=()=>[...(kbEl()?.querySelectorAll('#kbArea .kcard')||[])].map(c=>c.dataset.id);
function kbToggle(id){KFail.delete(id);KSel.has(id)?KSel.delete(id):KSel.add(id);KSelLast=id;kbSelPaint()}
function kbRange(id){const order=kbVisible(),a=order.indexOf(KSelLast),b=order.indexOf(id);if(a<0||b<0)KSel.add(id);else for(let i=Math.min(a,b);i<=Math.max(a,b);i++)KSel.add(order[i]);KSelLast=id;kbSelPaint()}
ACT['kb-sel']=(a,e)=>{e?.stopPropagation();if(e?.shiftKey&&KSelLast){a.checked=true;return kbRange(a.dataset.id)}kbToggle(a.dataset.id)};
ACT['kb-selcol']=a=>{const ids=[...(kbEl()?.querySelectorAll(`.kcol[data-col="${a.dataset.col}"] .kcard`)||[])].map(c=>c.dataset.id);const all=ids.every(i=>KSel.has(i));ids.forEach(i=>all?KSel.delete(i):KSel.add(i));KSelLast=ids[0]||KSelLast;kbSelPaint()};
ACT['kb-selall']=()=>{kbVisible().forEach(i=>KSel.add(i));kbSelPaint()};
ACT['kb-selclear']=()=>{KSel.clear();KFail.clear();KSelLast=null;const el=kbEl();el?.querySelectorAll('.kcard.failed').forEach(c=>{c.classList.remove('failed');c.querySelector('.kerr')?.remove()});kbSelPaint()};
ACT['kb-copyid']=(a,e)=>{e?.stopPropagation();navigator.clipboard?.writeText(a.dataset.id).then(()=>toast('Task number copied'),()=>toast('Could not copy','err'))};
// the bar at the bottom while tasks are selected: drawn once when it appears, then only its count changes
function kbBulk(el){const box=el.querySelector('#kbBulk');if(!box)return;const n=KSel.size;
 if(!n){const bar=box.querySelector('.kbulk');if(bar&&!bar.classList.contains('closing')){bar.classList.add('closing');setTimeout(()=>{if(!KSel.size)box.innerHTML=''},200)}return}
 const cur=box.querySelector('.kbulk:not(.closing)');if(cur){cur.querySelector('.kbulk-n').textContent=n+' selected';return}
 const ag=Pages._kb?.assignees||[];
 box.innerHTML=`<div class="kbulk" role="region" aria-label="Selected tasks"><b class="kbulk-n">${n} selected</b><div class="kbulk-acts"><button class="small" data-act="kb-bulk" data-s="todo">To do</button><button class="small" data-act="kb-bulk" data-s="ready">Ready</button><button class="small" data-act="kb-bulk" data-s="blocked">Block</button><button class="small" data-act="kb-bulk" data-s="ready" data-unblock="1">Unblock</button><button class="small" data-act="kb-bulk" data-s="done">Done</button><button class="small" data-act="kb-bulk" data-s="archived">Archive</button><button class="small ghost" style="color:var(--bad)" data-act="kb-bulk-del">${icon('trash',14)}Delete</button></div>
 <div class="kbulk-acts kbulk-x"><input id="kbBP" type="number" step="1" inputmode="numeric" placeholder="Priority" aria-label="Priority" style="width:104px"><button class="small" data-act="kb-bulk-pri">Set</button><select id="kbBA" style="width:auto" aria-label="Give to"><option value="">Give to…</option><option value="__none__">Nobody</option>${ag.map(x=>`<option value="${esc(x)}">${esc(ident(x).name)}</option>`).join('')}</select><label class="ktg"><input type="checkbox" id="kbBR"><span>Take it back from the current agent first</span></label><button class="small" data-act="kb-bulk-agent">Apply</button></div>
 <div class="kbulk-acts"><button class="small ghost kbulk-more" data-act="kb-bulk-more" aria-expanded="false">More</button><button class="small ghost" data-act="kb-selall">Select all shown</button><button class="small ghost" data-act="kb-selclear">Clear</button></div></div>`}
function kbBulkResult(r,n,what){const bad=(r?.results||[]).filter(x=>!x.ok);KSel.clear();KSelLast=null;KFail.clear();bad.forEach(x=>KFail.set(x.id,kbPlain(x.error||'Could not change')));Pages._kbSig=null;
 if(bad.length)toast(`${bad.length} of ${n} could not change. They are outlined on the board: ${kbPlain(bad[0].error||'')}`,'err');else toast(what||'Done')}
ACT['kb-bulk']=a=>kbMove([...KSel],a.dataset.s,{unblock:!!a.dataset.unblock});
ACT['kb-bulk-pri']=async()=>{const v=$('#kbBP')?.value;if(v===''||v==null)return toast('Type a priority number first','err');const ids=[...KSel];try{const r=await post(KB,'/tasks/bulk',{ids,priority:parseInt(v,10)||0});kbBulkResult(r,ids.length,'Priority set');kbRefresh()}catch(e){fail(e)}};
ACT['kb-bulk-agent']=async()=>{const v=$('#kbBA')?.value;if(!v)return toast('Choose an agent first','err');const ids=[...KSel];try{const r=await post(KB,'/tasks/bulk',{ids,assignee:v==='__none__'?'':v,reclaim_first:!!$('#kbBR')?.checked});kbBulkResult(r,ids.length,v==='__none__'?'Unassigned':'Given to '+ident(v).name);kbRefresh()}catch(e){fail(e)}};
ACT['kb-bulk-del']=()=>kbDelete([...KSel]);
ACT['kb-bulk-more']=a=>{const b=a.closest('.kbulk'),on=!b.classList.contains('open');b.classList.toggle('open',on);a.setAttribute('aria-expanded',on);a.textContent=on?'Less':'More'};
async function kbDelete(ids){const n=ids.length;if(!n)return;if(!await confirmBox(n>1?`Delete ${n} tasks?`:'Delete this task?','They are removed from the board for good. Archive keeps them instead.'))return;
 const rs=await Promise.all(ids.map(id=>del(KB,'/tasks/'+encodeURIComponent(id)).then(()=>({id,ok:true}),e=>({id,ok:false,error:e.message}))));kbBulkResult({results:rs},n,n>1?n+' tasks deleted':'Task deleted');closeLayers();kbRefresh()}
// one way to move tasks, from a drop, a task's buttons or the bulk bar: Block and Archive ask first, Done asks what was done
async function kbMove(ids,s,o={}){const n=ids.length,many=n>1;if(!n)return false;
 const cf={blocked:[many?`Block ${n} tasks?`:'Block this task?','The agent stops working on it until someone unblocks it.','Block'],archived:[many?`Archive ${n} tasks?`:'Archive this task?','It leaves the board but is kept. Turn on Archived to see it and bring it back.','Archive']}[s];
 if(cf&&!await confirmBox(cf[0],cf[1],cf[2]))return false;
 let summary;if(s==='done'){summary=await promptBox(many?`What was done in these ${n} tasks?`:'What was done?','A short summary, kept as the result','','Mark done');if(summary===null)return false;summary=summary.trim();if(!summary){toast('Write a short summary of what was done first','err');return false}}
 const body=s==='archived'&&many?{archive:true}:{status:s};if(summary)Object.assign(body,{result:summary,summary});
 const word={todo:'Moved to To do',triage:'Moved to Triage',ready:o.unblock?'Unblocked':'Moved to Ready',blocked:'Blocked',done:'Marked done',archived:'Archived'}[s];
 try{if(many){const r=await post(KB,'/tasks/bulk',{ids,...body});kbBulkResult(r,n,word)}else{const r=await KB('/tasks/'+encodeURIComponent(ids[0]),{method:'PATCH',body});KFail.delete(ids[0]);toast(r?.warning||word)}kbRefresh();kbDrawerLive(ids[0]);return true}
 catch(e){fail({...e,message:kbPlain(e.message)});kbRefresh();return false}}

/* ---------- dragging: mouse, touch, a trash zone, and grabbing the board to scroll it ---------- */
function kbDragOn(on){const el=kbEl();if(!el)return;Pages._kbDrag=on;el.classList.toggle('kdragging',on);el.querySelector('.kboard')?.classList.toggle('kdrag',on);el.querySelector('#kbTrash')?.classList.toggle('on',on);if(!on){el.querySelectorAll('.kcol.over,.kcol.no').forEach(c=>c.classList.remove('over','no'));el.querySelector('#kbTrash')?.classList.remove('over');setTimeout(()=>{if(!Pages._kbDrag&&Pages._kbPending){Pages._kbPending=0;kbRefresh()}},50)}}
const kbIdsFor=id=>KSel.has(id)&&KSel.size>1?[...KSel]:[id];
function kbDropOn(tgt,id){if(!tgt||!id)return;if(tgt.closest('#kbTrash'))return kbDelete(kbIdsFor(id));const col=tgt.closest('.kcol');if(!col||col.classList.contains('knodrop'))return;const s=col.dataset.col,ids=kbIdsFor(id);
 const cur=kbAll().find(t=>t.id===id)?.status;if(ids.length===1&&cur===s)return;kbMove(ids,s,{unblock:cur==='blocked'&&s==='ready'})}
function kbDrag(el){const trash=el.querySelector('#kbTrash');
 el.querySelectorAll('.kcard').forEach(c=>{c.ondragstart=e=>{e.dataTransfer.setData('text/kb',c.dataset.id);e.dataTransfer.effectAllowed='move';c.classList.add('dragging');
   if(KSel.has(c.dataset.id)&&KSel.size>1){const g=document.createElement('div');g.className='kghost';g.textContent=KSel.size+' tasks';document.body.append(g);e.dataTransfer.setDragImage(g,10,10);requestAnimationFrame(()=>g.remove())}
   requestAnimationFrame(()=>kbDragOn(true))};c.ondragend=()=>{c.classList.remove('dragging');kbDragOn(false)}});
 const over=(z,e)=>{if(!e.dataTransfer.types.includes('text/kb'))return;if(z.classList.contains('knodrop')){z.classList.add('no');e.dataTransfer.dropEffect='none';return}e.preventDefault();z.classList.add('over')};
 el.querySelectorAll('.kcol').forEach(col=>{col.ondragover=e=>over(col,e);col.ondragleave=e=>{if(!col.contains(e.relatedTarget))col.classList.remove('over','no')};col.ondrop=e=>{e.preventDefault();col.classList.remove('over');kbDragOn(false);kbDropOn(col,e.dataTransfer.getData('text/kb'))}});
 if(trash&&!trash._b){trash._b=1;trash.ondragover=e=>over(trash,e);trash.ondragleave=()=>trash.classList.remove('over');trash.ondrop=e=>{e.preventDefault();kbDragOn(false);kbDropOn(trash,e.dataTransfer.getData('text/kb'))}}}
// phones: hold a card for a moment, then move it and let go over a column (or the trash)
function kbTouch(area){if(!area||area._kt)return;area._kt=1;let timer=0,drag=null,sx=0,sy=0;
 const hit=(x,y)=>{const t=document.elementFromPoint(x,y);const el=kbEl();el?.querySelectorAll('.kcol.over,.kcol.no').forEach(c=>c.classList.remove('over','no'));el?.querySelector('#kbTrash')?.classList.remove('over');const z=t?.closest('#kbTrash,.kcol');if(z)z.classList.add(z.classList.contains('knodrop')?'no':'over');return t};
 area.addEventListener('touchstart',e=>{const c=e.target.closest('.kcard');if(!c||e.touches.length>1||e.target.closest('input,button'))return;const p=e.touches[0];sx=p.clientX;sy=p.clientY;clearTimeout(timer);
  timer=setTimeout(()=>{const r=c.getBoundingClientRect(),g=c.cloneNode(true);g.classList.add('kghost-card');g.style.width=r.width+'px';g.style.left=r.left+'px';g.style.top=r.top+'px';document.body.append(g);drag={c,g,ox:sx,oy:sy};c.classList.add('dragging');kbDragOn(true);navigator.vibrate?.(12)},380)},{passive:true});
 area.addEventListener('touchmove',e=>{const p=e.touches[0];if(!drag){if(Math.hypot(p.clientX-sx,p.clientY-sy)>8)clearTimeout(timer);return}e.preventDefault();drag.g.style.transform=`translate(${p.clientX-drag.ox}px,${p.clientY-drag.oy}px) rotate(2deg)`;hit(p.clientX,p.clientY);
  const k=kbEl()?.querySelector('.kboard'),w=innerWidth;if(k){if(p.clientX>w-40)k.scrollLeft+=12;else if(p.clientX<40)k.scrollLeft-=12}},{passive:false});
 const stop=(e,drop)=>{clearTimeout(timer);if(!drag)return;const d=drag;drag=null;d.g.remove();d.c.classList.remove('dragging');const p=e.changedTouches?.[0];const t=drop&&p?document.elementFromPoint(p.clientX,p.clientY):null;kbDragOn(false);if(e.cancelable)e.preventDefault();if(t)kbDropOn(t,d.c.dataset.id)};
 area.addEventListener('touchend',e=>stop(e,true));area.addEventListener('touchcancel',e=>stop(e,false));
 const trash=kbEl()?.querySelector('#kbTrash');if(trash)trash.addEventListener('touchmove',e=>e.preventDefault(),{passive:false})}
// grab empty board space with the mouse and drag sideways to scroll through the columns
function kbPan(area){if(!area||area._kp)return;area._kp=1;area.addEventListener('mousedown',e=>{if(e.button!==0||e.target.closest('.kcard,button,input,select,label,a,.empty-hero'))return;const k=e.target.closest('.kboard');if(!k)return;
 const x0=e.clientX,s0=k.scrollLeft;e.preventDefault();const mv=ev=>{const dx=ev.clientX-x0;if(Math.abs(dx)>3)k.classList.add('panning');k.scrollLeft=s0-dx};const up=()=>{k.classList.remove('panning');removeEventListener('mousemove',mv);removeEventListener('mouseup',up);};addEventListener('mousemove',mv);addEventListener('mouseup',up)})}

/* ---------- live updates: the engine's task-event stream (polling stays as the fallback) ---------- */
function kbLive(){const slug=kbSlug()||'default',w=Pages._kbWs;if(w&&w._slug===slug&&w.readyState<2)return;Pages._kbWs=null;try{w?.close()}catch{}
 const q=new URLSearchParams({profile:agentProfile()||'default',since:String(Pages._kb?.latest_event_id||0)});if(kbSlug())q.set('board',kbSlug());
 let ws;try{ws=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/hapi/plugins/kanban/events?'+q)}catch{return}ws._slug=slug;Pages._kbWs=ws;
 ws.onopen=()=>{Pages._kbBack=1000;Pages._kbWsOn=true};
 ws.onmessage=m=>{if(route().page?.id!=='kanban'){ws.close();return}let x;try{x=JSON.parse(m.data)}catch{return}if(!x?.events?.length)return;const ids=new Set(x.events.map(e=>e.task_id).filter(Boolean));
  clearTimeout(Pages._kbSoon);Pages._kbSoon=setTimeout(()=>{if(Pages._kbDrag){Pages._kbPending=1;return}const el=kbEl();if(el)kbLoad(el).catch(()=>{});const d=Pages._kbD;if(d&&ids.has(d.id))kbDrawerLive()},250)};
 ws.onclose=ev=>{if(Pages._kbWs!==ws)return;Pages._kbWs=null;Pages._kbWsOn=false;if(ev.code===1008||route().page?.id!=='kanban')return;const b=Pages._kbBack=Math.min((Pages._kbBack||1000)*2,30000);setTimeout(()=>{if(route().page?.id==='kanban'&&!Pages._kbWs)kbLive()},b)}}
addEventListener('hashchange',()=>{if(route().page?.id!=='kanban'){KSel.clear();KFail.clear()}if(route().page?.id!=='kanban'&&Pages._kbWs){const w=Pages._kbWs;Pages._kbWs=null;Pages._kbWsOn=false;try{w.close()}catch{}}});

/* ---------- boards: switch, create, settings, archive ---------- */
function kbSwitch(slug){store.set('kb-board',slug);KSel.clear();KFail.clear();Pages._kbSig=null;const w=Pages._kbWs;Pages._kbWs=null;Pages._kbWsOn=false;try{w?.close()}catch{}const el=kbEl();if(el){el.innerHTML=skeleton();kbLoad(el).then(()=>kbLive()).catch(e=>showError(el,e))}kbBoards()}
ACT['kb-boards']=async a=>{if(!Pages._kbBoards)await kbBoards();const cur=kbSlug()||Pages._kbCur||'default',list=Pages._kbBoards||[];
 menu(a,[{header:'Boards'},...list.map(b=>({label:(b.icon?b.icon+' ':'')+(b.name||b.slug),sub:plural(b.total||0,'task')+(b.project_name?' · '+b.project_name:''),on:b.slug===cur,run:()=>{if(b.slug!==cur)kbSwitch(b.slug)}})),'-',{label:'New board',icon:'plus',run:()=>ACT['kb-board-new']()},{label:'Board settings',icon:'settings',run:()=>ACT['kb-settings']()}],{search:list.length>8})};
const kbProjects=()=>Pages._kbProj?Promise.resolve(Pages._kbProj):KB('/projects').then(r=>Pages._kbProj=r.projects||[]).catch(()=>[]);
const kbSlugOf=s=>String(s||'').toLowerCase().normalize('NFKD').replace(/[^\w\s-]/g,'').trim().replace(/[\s_]+/g,'-').replace(/-+/g,'-').slice(0,40);
ACT['kb-board-new']=async()=>{const pj=await kbProjects();
 const d=drawer('New board',`<p class="hint" style="margin:0 0 6px">A separate board with its own tasks, for a project or a team.</p><label>Name</label><input id="knN" placeholder="Website relaunch"><label>Short name</label><input id="knS" placeholder="website-relaunch" autocapitalize="none" spellcheck="false"><p class="hint">Used to pick this board in commands. Letters, numbers and dashes.</p>
  <label>What it is for</label><input id="knD" placeholder="Everything for the new website">
  <div class="sched-row"><div><label>Icon</label><input id="knI" maxlength="4" placeholder="🚀" style="width:90px"></div>${pj.length?`<div><label>Project</label><select id="knP"><option value="">None</option>${pj.map(x=>`<option value="${esc(x.id)}">${esc(x.name||x.slug)}</option>`).join('')}</select></div>`:''}</div>
  <label>Folder its tasks work in</label><input id="knW" placeholder="/home/you/projects/website" autocapitalize="none" spellcheck="false"><p class="hint">Optional. A full path on the AI box. New tasks use it unless you choose another.</p>
  <label class="ktg" style="margin-top:14px">${toggle(true,'Open it now','id="knGo2"')}<span>Open it now</span></label>`,`<button class="ghost" data-act="close">Cancel</button><button class="primary" id="knGo">Create board</button>`);
 let auto=true;const n=d.querySelector('#knN'),s=d.querySelector('#knS');n.oninput=()=>{if(auto)s.value=kbSlugOf(n.value)};s.oninput=()=>{auto=!s.value};n.onkeydown=e=>{if(e.key==='Enter')d.querySelector('#knGo').click()};
 d.querySelector('#knGo').onclick=async()=>{const slug=kbSlugOf(s.value||n.value);if(!slug)return toast('Give the board a name','err');
  try{const r=await post(KB,'/boards',{slug,name:n.value.trim()||undefined,description:$('#knD').value.trim()||undefined,icon:$('#knI').value.trim()||undefined,project_id:$('#knP')?.value||undefined,default_workdir:$('#knW').value.trim()||undefined});closeLayers();toast('Board created');Pages._kbBoards=null;if($('#knGo2')?.checked!==false&&r?.board?.slug)kbSwitch(r.board.slug);else kbBoards()}catch(e){fail(e)}}};
ACT['kb-settings']=async()=>{await kbBoards();const m=kbMeta()||{slug:kbSlug()||'default'};const [pj,o,pr]=await Promise.all([kbProjects(),KB('/orchestration').catch(()=>null),KB('/profiles').then(r=>r.profiles||[]).catch(()=>[])]);
 const pick=(id,cur,res)=>`<select id="${id}"><option value="">Not set${res?' (uses '+esc(ident(res).name)+')':''}</option>${pr.map(x=>`<option value="${esc(x.name)}" ${x.name===cur?'selected':''}>${esc(ident(x.name).name)}</option>`).join('')}</select>`;
 const d=drawer('Board settings',`<h3 class="kd-h">This board</h3><label>Name</label><input id="ksN" value="${esc(m.name||'')}" placeholder="${esc(m.slug)}"><label>What it is for</label><input id="ksD" value="${esc(m.description||'')}">
  <div class="sched-row"><div><label>Icon</label><input id="ksI" maxlength="4" value="${esc(m.icon||'')}" style="width:90px"></div>${pj.length||m.project_id?`<div><label>Project</label><select id="ksP"><option value="">None</option>${pj.map(x=>`<option value="${esc(x.id)}" ${x.id===m.project_id?'selected':''}>${esc(x.name||x.slug)}</option>`).join('')}${m.project_id&&!pj.some(x=>x.id===m.project_id)?`<option value="${esc(m.project_id)}" selected>${esc(m.project_name||m.project_id)}</option>`:''}</select></div>`:''}</div>
  <label>Folder its tasks work in</label><input id="ksW" value="${esc(m.default_workdir||'')}" placeholder="Not set: tasks get a temporary folder" autocapitalize="none" spellcheck="false"><p class="hint">A full path on the AI box. Leave empty to clear it.</p>
  ${o?`<h3 class="kd-h" style="margin-top:22px">Who organises the work</h3><label>Organiser</label>${pick('ksO',o.orchestrator_profile,o.resolved_orchestrator_profile)}<p class="hint">The agent that writes out and splits new ideas into tasks.</p><label>Default agent</label>${pick('ksA',o.default_assignee,o.resolved_default_assignee)}<p class="hint">Gets new tasks nobody was chosen for.</p>
  <label class="ktg" style="margin-top:12px">${toggle(o.auto_decompose,'Split new ideas automatically','id="ksX"')}<span>Split new ideas into tasks automatically<small>Off: you press Split into tasks on each idea yourself.</small></span></label>`:''}
  ${m.slug!=='default'?`<button class="ghost" style="margin-top:22px;color:var(--bad)" id="ksDel">${icon('trash',15)}Archive this board</button>`:''}`,`<button class="ghost" data-act="close">Cancel</button><button class="primary" id="ksGo">Save</button>`,{size:'md'});
 d.querySelector('#ksDel')?.addEventListener('click',async()=>{if(!await confirmBox('Archive this board?','Its tasks leave the dashboard. The board is kept on the AI box and can be brought back from there.','Archive'))return;try{await del(KB,'/boards/'+encodeURIComponent(m.slug));closeLayers();toast('Board archived');kbSwitch('')}catch(e){fail(e)}});
 d.querySelector('#ksGo').onclick=async()=>{const b={};const v=id=>$(id)?.value.trim();if(v('#ksN')!==(m.name||''))b.name=v('#ksN');if(v('#ksD')!==(m.description||''))b.description=v('#ksD');if(v('#ksI')!==(m.icon||''))b.icon=v('#ksI');if($('#ksP')&&v('#ksP')!==(m.project_id||''))b.project_id=v('#ksP');if(v('#ksW')!==(m.default_workdir||''))b.default_workdir=v('#ksW');
  const ob={};if(o){if(v('#ksO')!==(o.orchestrator_profile||''))ob.orchestrator_profile=v('#ksO');if(v('#ksA')!==(o.default_assignee||''))ob.default_assignee=v('#ksA');const x=$('#ksX')?.checked;if(x!==undefined&&x!==!!o.auto_decompose)ob.auto_decompose=x}
  if(!Object.keys(b).length&&!Object.keys(ob).length)return closeLayers();
  try{if(Object.keys(b).length)await KB('/boards/'+encodeURIComponent(m.slug),{method:'PATCH',body:b});if(Object.keys(ob).length)Pages._kbOrch=await put(KB,'/orchestration',ob);closeLayers();toast('Board settings saved');const r=kbEl()?.querySelector('#kbToolR');if(r)r._sig=null;kbRefresh()}catch(e){fail(e)}}};
ACT['kb-dispatch']=async()=>{try{const r=await post(KB,'/dispatch?max=8');const c=x=>Array.isArray(x)?x.length:typeof x==='number'?x:0;const n=c(r?.spawned)||c(r?.claimed)||c(r?.started);toast(n?plural(n,'task')+' picked up':'Asked the agents to pick up Ready tasks');kbRefresh()}catch(e){fail(e)}};
ACT['kb-refresh']=()=>{Pages._kbSig=null;Pages._kbCfg=null;reload()};

/* ---------- a new task ---------- */
ACT['kb-new']=a=>{const col=a?.dataset?.col||'todo';const b=Pages._kb||{};const ag=b.assignees||['default'];const bm=kbMeta();const tasks=kbAll().filter(t=>t.status!=='archived');
 const d=drawer('New task',`<label>Title</label><input id="ktT" placeholder="Write the weekly newsletter"><label>Details</label><textarea id="ktB" rows="5" placeholder="What done looks like, links, anything the agent needs."></textarea>
  <div class="sched-row"><div><label>Agent</label><select id="ktA"><option value="">Nobody yet</option>${ag.map(n=>`<option value="${esc(n)}" ${KF.agent===n?'selected':''}>${esc(ident(n).name)}</option>`).join('')}</select></div><div><label>Priority</label><input id="ktP" type="number" step="1" inputmode="numeric" value="0"></div></div><p class="hint">Higher priority is picked up first.</p>
  <label>Put it in</label><select id="ktS">${[['triage','Triage: an agent writes it out first'],['todo','To do'],['ready','Ready: the agent starts right away']].map(([v,l])=>`<option value="${v}" ${v===col?'selected':''}>${l}</option>`).join('')}</select>
  ${tasks.length?`<label>Waits for</label><select id="ktW"><option value="">Nothing, it can start any time</option>${tasks.map(t=>`<option value="${esc(t.id)}">${esc(t.title||t.id)}</option>`).join('')}</select><p class="hint">It stays in To do until that task is done.</p>`:''}
  <details class="kd-fold"><summary>More options</summary><div>
   <label>Skills it should use</label><input id="ktK" placeholder="writing, research" autocapitalize="none"><p class="hint">Extra skills for this task, separated by commas.</p>
   <label>Where it works</label><select id="ktWk">${[['scratch','A temporary folder, cleared afterwards'],['worktree','Its own copy of a Git project'],['dir','A folder that is kept']].map(([v,l])=>`<option value="${v}" ${v===(bm?.default_workspace_kind||'scratch')?'selected':''}>${l}</option>`).join('')}</select>
   <div id="ktWb" class="kd-reveal"><div><input id="ktWp" value="${esc(bm?.default_workdir||'')}" placeholder="/home/you/projects/site" autocapitalize="none" spellcheck="false" style="margin-top:8px"><p class="hint" id="ktWh"></p></div></div>
   <label class="ktg" style="margin-top:14px">${toggle(false,'Keep going until it is done','id="ktG"')}<span>Keep going until it is done<small>The agent takes more turns until the goal is met.</small></span></label>
   <div id="ktGb" class="kd-reveal"><div><label>At most this many turns</label><input id="ktGn" type="number" min="1" inputmode="numeric" placeholder="No limit"></div></div></div></details>`,`<button class="ghost" data-act="close">Cancel</button><button class="primary" id="ktGo">Add task</button>`);
 const wk=d.querySelector('#ktWk'),wb=d.querySelector('#ktWb'),wh=d.querySelector('#ktWh');const ws=()=>{wb.classList.toggle('open',wk.value!=='scratch');wh.textContent=wk.value==='worktree'?'The Git project to copy. Leave empty to use the board\'s folder.':'Needed unless the board has a folder.'};wk.onchange=ws;ws();
 d.querySelector('#ktG').onchange=e=>d.querySelector('#ktGb').classList.toggle('open',e.target.checked);
 d.querySelector('#ktT').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();d.querySelector('#ktGo').click()}};
 d.querySelector('#ktGo').onclick=async e=>{const go=e.currentTarget;if(go.disabled)return;const title=$('#ktT').value.trim();if(!title)return toast('Give the task a title','err');const status=$('#ktS').value;
  const body={title,body:$('#ktB').value.trim()||undefined,assignee:$('#ktA').value||undefined,priority:parseInt($('#ktP').value,10)||0,triage:status==='triage'};
  const w=$('#ktW')?.value;if(w)body.parents=[w];const sk=$('#ktK').value.split(',').map(x=>x.trim()).filter(Boolean);if(sk.length)body.skills=sk;
  if(wk.value!=='scratch'){body.workspace_kind=wk.value;const pth=$('#ktWp').value.trim();if(pth)body.workspace_path=pth}
  if($('#ktG').checked){body.goal_mode=true;const g=parseInt($('#ktGn').value,10);if(g>0)body.goal_max_turns=g}
  // one task per press: the button (and Enter, which presses it) waits for the answer
  go.disabled=true;try{const r=await post(KB,'/tasks',body);const id=r?.task?.id;let note=r?.warning?kbPlain(r.warning):'';
   // the engine decides where a new task lands (no parents: Ready when it has an agent); put it where the person chose
   if(id&&status!=='triage'&&r.task.status!==status&&!(w&&status==='ready'))try{await KB('/tasks/'+encodeURIComponent(id),{method:'PATCH',body:{status}})}catch(e2){note=kbPlain(e2.message)}
   closeLayers();toast(note||'Task added',note&&!r?.warning?'err':undefined);kbRefresh()}catch(e){fail(e)}finally{go.disabled=false}}};

/* ---------- one task ---------- */
const kbStatusBtns=k=>{const s=k.status,id=esc(k.id),b=(lab,st,ok,ic,x='')=>ok?`<button class="small" data-act="kb-status" data-id="${id}" data-s="${st}" ${x}>${ic?icon(ic,14):''}${lab}</button>`:'';
 return `<div class="kd-acts">${s==='triage'?`<button class="small" data-act="kb-specify" data-id="${id}" title="An agent writes the idea out as a clear task">${icon('sparkle',14)}Write it out</button><button class="small" data-act="kb-decompose" data-id="${id}" title="An agent splits the idea into smaller tasks">${icon('layers',14)}Split into tasks</button>`:''}
  ${b('Back to Triage','triage',!['triage','archived'].includes(s))}${b('To do','todo',!['todo','running','archived'].includes(s))}${b('Ready','ready',!['ready','blocked','archived'].includes(s))}${b('Unblock','ready',s==='blocked','','data-unblock="1"')}${b('Block','blocked',s==='running'||s==='ready')}${b('Done','done',['running','ready','blocked','review'].includes(s),'check')}${s==='archived'?b('Bring back','todo',true,'refresh'):b('Archive','archived',true)}</div>`};
// what went wrong, with the engine's suggested fixes
const kbDiags=(k,ag)=>{const ds=k.diagnostics||[];if(!ds.length)return '';
 const act=(g,x,i)=>{const kind=x.kind,sug=x.suggested?' primary':'';if(kind==='unblock')return `<button class="small${sug}" data-act="kb-status" data-id="${esc(k.id)}" data-s="ready" data-unblock="1">Unblock</button>`;
  if(kind==='reclaim')return `<button class="small${sug}" data-act="kb-reclaim" data-id="${esc(k.id)}" data-kind="${esc(g.kind)}">Take it back from the agent</button>`;
  if(kind==='reassign')return `<span class="kd-give"><select class="kd-giveS" style="width:auto" aria-label="Give it to"><option value="">Nobody</option>${ag.map(n=>`<option value="${esc(n)}" ${n===k.assignee?'selected':''}>${esc(ident(n).name)}</option>`).join('')}</select><button class="small${sug}" data-act="kb-reassign" data-id="${esc(k.id)}" data-kind="${esc(g.kind)}" data-rf="${x.payload?.reclaim_first?1:''}">Give it to them</button></span>`;
  if(kind==='cli_hint')return `<button class="small ghost" data-act="kb-copycmd" data-cmd="${esc(x.payload?.command||x.label||'')}">${icon('copy',14)}Copy the fix command</button>`;
  if(kind==='comment')return `<button class="small ghost" data-act="kb-gocomment">${icon('chat',14)}Add a comment</button>`;
  if(kind==='open_docs'&&/^https?:/.test(x.payload?.url||''))return `<a class="small btnlink" href="${esc(x.payload.url)}" target="_blank" rel="noopener">${esc(kbPlain(x.label||'Read more'))}</a>`;return ''};
 return `<div class="kd-sec"><h3>What went wrong</h3>${ds.map(g=>{const data=g.data&&Object.keys(g.data).length?g.data:null;return `<div class="kdiag ${esc(g.severity||'warning')}"><b>${icon('alert',14)}${esc(kbPlain(g.title||kbHum(g.kind)))}</b>${g.detail?`<p>${esc(kbPlain(g.detail))}</p>`:''}
  ${data?`<details class="kd-fold"><summary>Details</summary><div><dl class="kd-meta">${Object.entries(data).map(([a,v])=>`<div><dt>${esc(kbHum(a))}</dt><dd>${esc(kbPlain(Array.isArray(v)?v.join(', '):typeof v==='object'?JSON.stringify(v):String(v)))}</dd></div>`).join('')}</dl></div></details>`:''}
  <div class="kd-acts">${(g.actions||[]).map((x,i)=>act(g,x,i)).join('')}</div></div>`}).join('')}</div>`};
const kbWork={scratch:'A temporary folder',worktree:'Its own copy of a Git project',dir:'A folder that is kept'};
const kbRunWord={completed:'Finished',done:'Finished',reclaimed:'Taken back',failed:'Failed',crashed:'Stopped unexpectedly',timed_out:'Ran out of time',timeout:'Ran out of time',blocked:'Blocked',gave_up:'Gave up',review:'Sent for review'};
const kbDiagEv={completion_blocked_hallucination:'Could not finish: it mentioned tasks that do not exist',suspected_hallucinated_references:'Mentioned tasks that do not exist'};
function kbTaskTop(t){const k=t.task||t,st=KCOLS.find(c=>c[0]===k.status);
 return `<div class="kd-chips"><span class="chip blue">${esc(st?st[1]:kbHum(k.status))}</span>${k.assignee?`<span class="chip">${esc(ident(k.assignee).name)}</span>`:''}<button class="chip kid" data-act="kb-copyid" data-id="${esc(k.id)}" title="Copy the task number">#${esc(k.id)}</button>${k.created_at?`<span class="chip">Added ${esc(ago(k.created_at))}</span>`:''}</div>${kbStatusBtns(k)}${k.block_reason?`<p class="err-line">Blocked: ${esc(kbPlain(k.block_reason))}</p>`:''}${kbDiags(k,Pages._kb?.assignees||[])}`}
function kbTaskL1(t){const k=t.task||t,links=t.links||{parents:[],children:[]},lt=Object.fromEntries((t.link_tasks||[]).map(x=>[x.id,x])),all=kbAll();
 const meta=[k.reasoning_effort&&['Thinking',kbHum(k.reasoning_effort)],['Works in',(kbWork[k.workspace_kind]||kbHum(k.workspace_kind||'scratch'))+(k.workspace_path?': '+k.workspace_path:'')],k.tenant&&['Group',k.tenant],k.skills?.length&&['Skills',k.skills.join(', ')],k.goal_mode&&['Keeps going',k.goal_max_turns?'Until done, at most '+k.goal_max_turns+' turns':'Until done'],k.created_by&&['Added by',k.created_by==='dashboard'?'The dashboard':ident(k.created_by).name||k.created_by],k.started_at&&['Started',ago(k.started_at)],k.completed_at&&['Finished',ago(k.completed_at)]].filter(Boolean);
 const link=(id,p,c)=>{const x=lt[id]||all.find(y=>y.id===id)||{};const s=KCOLS.find(z=>z[0]===x.status);return `<div class="kd-link"><button class="kd-linkb" data-act="kb-open" data-id="${esc(id)}">${esc(x.title||'#'+id)}</button>${s?`<span class="chip">${esc(s[1])}</span>`:''}<button class="ghost icon" data-act="kb-unlink" data-p="${esc(p)}" data-c="${esc(c)}" aria-label="Remove this link" title="Remove this link">${icon('x',14)}</button></div>`};
 const opts=ex=>all.filter(x=>x.id!==k.id&&!ex.includes(x.id)&&x.status!=='archived').map(x=>`<option value="${esc(x.id)}">${esc(x.title||x.id)}</option>`).join('');
 const res=k.result||k.latest_summary,cr=t.child_results||[];
 return `<dl class="kd-meta">${meta.map(([a,v])=>`<div><dt>${a}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>
 <div class="kd-sec"><h3>Waits for</h3>${links.parents.map(id=>link(id,id,k.id)).join('')||'<p class="hint">Nothing. It can start any time.</p>'}${opts(links.parents)?`<select class="kd-addS" data-rel="p" aria-label="Add a task it waits for"><option value="">Add a task it waits for…</option>${opts(links.parents)}</select>`:''}
  <h3 style="margin-top:14px">Waiting for this</h3>${links.children.map(id=>link(id,k.id,id)).join('')||'<p class="hint">No task waits for this one.</p>'}${opts(links.children)?`<select class="kd-addS" data-rel="c" aria-label="Add a task that waits for this"><option value="">Add a task that waits for this…</option>${opts(links.children)}</select>`:''}</div>
 ${res?`<div class="kd-sec"><h3>${k.result?'Result':'Result, from the agent\'s last run'}</h3>${kbMd(res)}</div>`:k.status==='done'?`<div class="kd-sec"><h3>Result</h3><p class="hint">${links.children.length?'This task handed its work to sub-tasks. See their results below.':'No result was written down. Check the runs or the agent log below.'}</p></div>`:''}
 ${cr.length?`<div class="kd-sec"><h3>Sub-task results <span class="n">${cr.length}</span></h3>${cr.map(c=>{const s=KCOLS.find(z=>z[0]===c.status),r=c.result||c.latest_summary;return `<div class="kd-child"><div class="kd-child-h"><b>${esc(c.title||'#'+c.id)}</b>${s?`<span class="chip">${esc(s[1])}</span>`:''}<button class="ghost small" data-act="kb-open" data-id="${esc(c.id)}">Open</button></div>${r?kbMd(r):'<p class="hint">No result yet.</p>'}</div>`}).join('')}</div>`:''}
 <div class="kd-sec"><h3>Files <span class="n">${(t.attachments||[]).length||''}</span></h3>${(t.attachments||[]).map(f=>`<div class="kd-file">${icon('file',15)}<span class="t">${esc(f.filename)}</span><small>${kbSize(f.size)}</small><button class="ghost icon" data-act="kb-att-get" data-aid="${esc(f.id)}" data-name="${esc(f.filename)}" aria-label="Download ${esc(f.filename)}" title="Download">${icon('download',15)}</button><button class="ghost icon" data-act="kb-att-del" data-aid="${esc(f.id)}" data-name="${esc(f.filename)}" aria-label="Delete ${esc(f.filename)}" title="Delete">${icon('trash',15)}</button></div>`).join('')||'<p class="hint">No files yet. The agent can read files you add here.</p>'}<button class="small" data-act="kb-att-pick" style="margin-top:8px">${icon('upload',14)}Add files</button></div>
 <div id="kdHome"></div>
 <div class="kd-sec"><h3>Comments <span class="n">${(t.comments||[]).length||''}</span></h3>${(t.comments||[]).map(c=>`<div class="kcomment"><b>${esc(c.author==='dashboard'?'The dashboard':c.author||'Someone')} <small>${esc(ago(c.created_at))}</small></b>${kbMd(c.body||'')}</div>`).join('')||'<p class="hint">No comments yet.</p>'}</div>`}
function kbTaskL2(t){const runs=t.runs||[],ev=t.events||[],all=Pages._kbRunsAll===(t.task||t).id;const vis=(all||runs.length<=3?runs:runs.slice(-3)).slice().reverse();
 const dur=r=>{if(!r.started_at)return '';const s=Math.max(0,(r.ended_at||Date.now()/1000)-r.started_at);return s<60?Math.round(s)+' s':s<3600?Math.round(s/60)+' min':(s/3600).toFixed(1)+' h'};
 return `${runs.length?`<div class="kd-sec"><h3>Runs <span class="n">${runs.length}</span></h3>${vis.map(r=>{const o=r.ended_at?(r.outcome||r.status||'ended'):'active',meta=r.metadata&&Object.keys(r.metadata).length?JSON.stringify(r.metadata,null,2):'';
  return `<div class="krun ${esc(o)}"><div class="krun-h"><b>${esc(r.ended_at?kbRunWord[o]||kbHum(o):'Working now')}</b><span>${esc(r.profile?ident(r.profile).name:'No agent')}</span><span>${dur(r)}</span><small>${esc(ago(r.started_at))}</small></div>${r.summary?`<p>${esc(kbPlain(r.summary))}</p>`:''}${r.error?`<p class="err-line">${esc(kbPlain(r.error))}</p>`:''}${meta?`<details class="kd-fold"><summary>More about this run</summary><div><pre class="log">${esc(meta)}</pre></div></details>`:''}</div>`}).join('')}${!all&&runs.length>3?`<button class="ghost small" data-act="kb-runs-all" data-id="${esc((t.task||t).id)}">Show ${runs.length-3} earlier</button>`:''}</div>`:''}
 ${ev.length?`<details class="kd-fold kd-sec" data-k="hist"><summary>History <span class="n">${ev.length}</span></summary><div>${ev.slice().reverse().slice(0,20).map(e=>{const dg=kbDiagEv[e.kind],ph=dg?(e.payload?.phantom_cards||e.payload?.phantom_refs||[]):[];
  return `<div class="kev ${dg?'bad':''}"><div class="kev-h"><b>${dg?icon('alert',13):''}${esc(dg||kbHum(e.kind))}</b><small>${esc(ago(e.created_at))}</small></div>${ph.length?`<p>Task numbers it made up: ${ph.map(x=>`<code>${esc(x)}</code>`).join(' ')}</p>`:''}${e.payload&&!dg?`<code class="kev-p">${esc(kbPlain(JSON.stringify(e.payload)))}</code>`:''}</div>`}).join('')}</div></details>`:''}`}
ACT['kb-open']=async(a,e)=>{const id=a.dataset.id;
 if(e&&a.classList?.contains('kcard')){if(e.shiftKey){e.preventDefault();return kbRange(id)}if(e.ctrlKey||e.metaKey){e.preventDefault();return kbToggle(id)}}
 let t;try{t=await KB('/tasks/'+encodeURIComponent(id))}catch(er){return fail(er)}const task=t.task||t;const ag=Pages._kb?.assignees||[];
 const mo=task.model_override?(task.provider_override?task.provider_override+'\u0000':'')+task.model_override:'';
 const d=drawer(task.title||'Task',`<div id="kdTop">${kbTaskTop(t)}</div><div id="kdMsg" class="kd-msg"></div>
  <div class="kd-edit"><label>Title</label><input id="kdT" value="${esc(task.title||'')}">
  <label>Details</label>${task.body&&Pages._kbCfg?.render_markdown!==false?`<div class="kd-read" id="kdBr">${kbMd(task.body)}<button class="ghost small" id="kdBe">${icon('edit',14)}Edit details</button></div>`:''}<textarea id="kdB" rows="6" ${task.body&&Pages._kbCfg?.render_markdown!==false?'hidden':''}>${esc(task.body||'')}</textarea>
  <div class="sched-row"><div><label>Agent</label><select id="kdA"><option value="">Nobody</option>${ag.map(n=>`<option value="${esc(n)}" ${n===task.assignee?'selected':''}>${esc(ident(n).name)}</option>`).join('')}</select></div><div><label>Priority</label><input id="kdP" type="number" step="1" inputmode="numeric" value="${esc(task.priority||0)}"></div></div>
  <label>Model for its next run</label><select id="kdM"><option value="">The agent's own model</option>${mo?`<option value="${esc(mo)}" selected>${esc(mo.replace('\u0000',': '))}</option>`:''}<option value="__type">Type a model name…</option></select></div>
  <div id="kdL1">${kbTaskL1(t)}</div>
  <div class="kd-cin"><input id="kdC" placeholder="Add a comment for the agent" aria-label="Comment"><button data-act="kb-comment" data-id="${esc(task.id)}">Add</button></div><p class="hint">The agent reads comments the next time it works on this task.</p>
  <div id="kdL2">${kbTaskL2(t)}</div>
  <details class="kd-fold kd-sec" id="kdLog"><summary>Agent log</summary><div class="kd-logbox"><p class="hint">Loading…</p></div></details><input type="file" id="kdUp" multiple hidden>`,
  `<button class="ghost" style="color:var(--bad);margin-right:auto" data-act="kb-del" data-id="${esc(task.id)}">${icon('trash',15)}Delete</button><button class="ghost" data-act="close">Close</button><button class="primary" id="kdGo">Save</button>`,{size:'lg'});
 Pages._kbD={id:task.id,d,t,sig:JSON.stringify(t)};kbBindTask(d);kbHome(d,task.id);kbModels(d.querySelector('#kdM'),mo);
 d.querySelector('#kdBe')?.addEventListener('click',()=>{d.querySelector('#kdBr').remove();const b=d.querySelector('#kdB');b.hidden=false;b.classList.add('kd-in');b.focus()});
 d.querySelector('#kdT').onkeydown=e2=>{if(e2.key==='Enter'){e2.preventDefault();d.querySelector('#kdGo').click()}};
 // Escape in a changed field puts its old text back instead of closing the task
 d.querySelectorAll('.kd-edit input,.kd-edit textarea').forEach(i=>i.addEventListener('keydown',e2=>{if(e2.key==='Escape'&&i.value!==i.defaultValue){e2.preventDefault();e2.stopPropagation();i.value=i.defaultValue}}));
 d.querySelector('#kdC').onkeydown=e2=>{if(e2.key==='Enter'&&!e2.shiftKey){e2.preventDefault();d.querySelector('[data-act="kb-comment"]').click()}};
 d.querySelector('#kdUp').onchange=e2=>kbUpload(task.id,[...e2.target.files]).finally(()=>{e2.target.value=''});
 d.querySelector('#kdLog').addEventListener('toggle',e2=>{if(e2.target.open)kbLog(d,task.id)});
 // only what the person changed since the drawer opened is sent: comparing with a fresher copy would undo others' changes
 d.querySelector('#kdGo').onclick=async()=>{const body={},cur=task;const T=$('#kdT').value.trim(),B=$('#kdB').value,A=$('#kdA').value,P=parseInt($('#kdP').value,10)||0,M=$('#kdM').value;
  if(!T)return toast('A task needs a title','err');if(T!==cur.title)body.title=T;if(B!==(cur.body||''))body.body=B;if(A!==(cur.assignee||''))body.assignee=A||'';if(P!==(cur.priority||0))body.priority=P;
  if(M!==mo&&M!=='__type'){if(!M)body.clear_model_override=true;else{const i=M.indexOf('\u0000');if(i<0)body.model_override=M;else{body.provider_override=M.slice(0,i);body.model_override=M.slice(i+1)}}}
  if(!Object.keys(body).length)return closeLayers();try{const r=await KB('/tasks/'+encodeURIComponent(task.id),{method:'PATCH',body});closeLayers();toast(r?.warning?kbPlain(r.warning):'Task saved');kbRefresh()}catch(e2){fail({...e2,message:kbPlain(e2.message)})}}};
// the parts of an open task that change while it runs are redrawn in place; what the person is typing stays
async function kbDrawerLive(id){const D=Pages._kbD;if(!D||!D.d.isConnected||id&&id!==D.id)return;let t;try{t=await KB('/tasks/'+encodeURIComponent(D.id))}catch{return}const sig=JSON.stringify(t);if(!D.d.isConnected||D.sig===sig)return;D.t=t;D.sig=sig;
 const open=new Set([...D.d.querySelectorAll('details[data-k][open]')].map(x=>x.dataset.k)),body=D.d.querySelector('.drawer-body'),y=body?.scrollTop;
 const top=D.d.querySelector('#kdTop'),l1=D.d.querySelector('#kdL1'),l2=D.d.querySelector('#kdL2');if(top)top.innerHTML=kbTaskTop(t);if(l1)l1.innerHTML=kbTaskL1(t);if(l2)l2.innerHTML=kbTaskL2(t);
 D.d.querySelectorAll('details[data-k]').forEach(x=>{if(open.has(x.dataset.k))x.open=true});if(body)body.scrollTop=y;kbBindTask(D.d);kbHome(D.d,D.id);if(D.d.querySelector('#kdLog')?.open)kbLog(D.d,D.id)}
function kbBindTask(d){d.querySelectorAll('.kd-addS').forEach(s=>s.onchange=async()=>{const v=s.value,id=Pages._kbD?.id;if(!v||!id)return;const b=s.dataset.rel==='p'?{parent_id:v,child_id:id}:{parent_id:id,child_id:v};try{await post(KB,'/links',b);toast('Linked');kbDrawerLive();kbRefresh()}catch(e){fail(e);s.value='';s._sync?.()}})}
async function kbModels(sel,cur){if(!sel)return;const c=Pages._kbModels||(Pages._kbModels=await KB('/model-options').catch(()=>({providers:[]})));if(!sel.isConnected||!c.providers?.length)return;
 const seen=new Set();let h=`<option value="">The agent's own model</option>`;for(const p of c.providers){h+=`<optgroup label="${esc(p.label||p.slug)}">${(p.models||[]).map(m=>{const v=p.slug+'\u0000'+m;seen.add(v);return `<option value="${esc(v)}">${esc(m)}</option>`}).join('')}</optgroup>`}
 if(cur&&!seen.has(cur))h+=`<option value="${esc(cur)}">${esc(cur.replace('\u0000',': '))}</option>`;h+=`<option value="__type">Type a model name…</option>`;const v=sel.value;sel.innerHTML=h;
 sel.value=[...sel.options].some(o=>o.value===v)?v:'';sel._sync?.()}
document.addEventListener('change',async e=>{const s=e.target;if(s.id!=='kdM'||s.value!=='__type')return;const v=await promptBox('Model for this task','Model name, as the provider writes it','','Use it');if(!v?.trim()){s.value='';s._sync?.();return}const o=document.createElement('option');o.value=v.trim();o.textContent=v.trim();s.insertBefore(o,s.lastElementChild);s.value=v.trim();s._sync?.()});
async function kbHome(d,id){const box=d.querySelector('#kdHome');if(!box)return;let r;try{r=await KB('/home-channels?task_id='+encodeURIComponent(id))}catch{return}const hs=r?.home_channels||[];if(!box.isConnected||!hs.length){box.innerHTML='';return}
 box.innerHTML=`<div class="kd-sec"><h3>Tell me on</h3>${hs.map(h=>`<label class="ktg kd-home">${toggle(h.subscribed,'Send updates to '+h.platform,`data-act="kb-home" data-id="${esc(id)}" data-pf="${esc(h.platform)}"`)}<span>${esc(kbHum(h.platform))}<small>${esc(h.name||'Home')}</small></span></label>`).join('')}<p class="hint">A message arrives there when the task is finished, gets blocked, or the agent gives up.</p></div>`}
ACT['kb-home']=async(a,e)=>{e?.stopPropagation();const on=a.checked,u='/tasks/'+encodeURIComponent(a.dataset.id)+'/home-subscribe/'+encodeURIComponent(a.dataset.pf);try{on?await post(KB,u):await del(KB,u);toast(on?'You will hear about it on '+kbHum(a.dataset.pf):'No more updates on '+kbHum(a.dataset.pf))}catch(er){a.checked=!on;fail(er)}};
async function kbLog(d,id){const box=d.querySelector('#kdLog .kd-logbox');if(!box)return;let r;try{r=await KB('/tasks/'+encodeURIComponent(id)+'/log?tail=100000')}catch(e){r=e.status===404?{exists:false}:{err:e.message}}if(!box.isConnected)return;
 box.innerHTML=r.err?`<p class="err-line">${esc(r.err)}</p>`:!r.exists?'<p class="hint">No log yet. The agent has not started on this task, or the log was cleared.</p>':`<div class="kd-log-h"><small>${kbSize(r.size_bytes)}</small><button class="ghost small" data-act="kb-log">${icon('refresh',14)}Refresh</button></div><pre class="log">${esc(kbPlain(r.content||'(empty)'))}</pre>${r.truncated?`<p class="hint">Showing the last 100 KB. The whole log is on the AI box: ${esc(r.path)}</p>`:''}`;
 const pre=box.querySelector('pre');if(pre)pre.scrollTop=pre.scrollHeight}
ACT['kb-log']=()=>{const D=Pages._kbD;if(D)kbLog(D.d,D.id)};
ACT['kb-runs-all']=a=>{Pages._kbRunsAll=a.dataset.id;const D=Pages._kbD;const l2=D?.d.querySelector('#kdL2');if(l2&&D.t)l2.innerHTML=kbTaskL2(D.t)};
ACT['kb-status']=a=>kbMove([a.dataset.id],a.dataset.s,{unblock:!!a.dataset.unblock});
ACT['kb-specify']=async a=>{const m=$('#kdMsg');try{const r=await post(KB,'/tasks/'+encodeURIComponent(a.dataset.id)+'/specify',{author:S.me?.name||undefined});
 if(m)m.innerHTML=r?.ok?`<p class="ok-line">${icon('check',14)}Written out${r.new_title?': now called “'+esc(r.new_title)+'”':''}.</p>`:`<p class="err-line">Could not write it out: ${esc(kbPlain(r?.reason||'no reason given'))}</p>`;if(r?.ok){kbDrawerLive();kbRefresh()}}catch(e){fail(e)}};
// one split at a time per task (the button is redrawn while it works, so a flag, not the button, remembers)
ACT['kb-decompose']=async a=>{const id=a.dataset.id;if((Pages._kbSplit??=new Set()).has(id))return;Pages._kbSplit.add(id);const m=$('#kdMsg');try{const r=await post(KB,'/tasks/'+encodeURIComponent(id)+'/decompose',{author:S.me?.name||undefined});
 if(m)m.innerHTML=!r?.ok?`<p class="err-line">Could not split it: ${esc(kbPlain(r?.reason||'no reason given'))}</p>`:r.fanout&&r.child_ids?.length?`<p class="ok-line">${icon('check',14)}Split into ${plural(r.child_ids.length,'task')}. They are on the board now.</p>`:`<p class="ok-line">${icon('check',14)}Kept as one task${r.new_title?', now called “'+esc(r.new_title)+'”':''}.</p>`;if(r?.ok){kbDrawerLive();kbRefresh()}}catch(e){fail(e)}finally{Pages._kbSplit.delete(id)}};
ACT['kb-reclaim']=async a=>{try{await post(KB,'/tasks/'+encodeURIComponent(a.dataset.id)+'/reclaim',{reason:'recovery action for '+a.dataset.kind});toast('Taken back. The task is Ready again.');kbDrawerLive();kbRefresh()}catch(e){fail({...e,message:kbPlain(e.message)})}};
