ACT['kb-del']=a=>kbDelete([a.dataset.id]);

/* ===================== Achievements ===================== */
const TIER_COLORS={Copper:'#b87333',Silver:'#9aa3ad',Gold:'#d4a017',Diamond:'#4fc3f7',Olympian:'#8e5cff'};
const ACH_F={cat:'All',vis:'all'};
const achDeH=s=>String(s||'').replace(/Hermes Agent/g,'aqeelOS').replace(/Hermes/g,'aqeelOS');
PAGES.achievements=async(p,el)=>{const gone=pageTok(el);
 setActions(`<button data-act="ach-rescan">${icon('refresh',16)}Rescan history</button>`);
 const [a,recent,scan]=await Promise.all([H('/plugins/hermes-achievements/achievements'),H('/plugins/hermes-achievements/recent-unlocks').catch(()=>null),H('/plugins/hermes-achievements/scan-status').catch(()=>null)]);if(gone())return;
 Pages._ach={a,recent,scan,list:(a.achievements||[]).map(x=>({...x,name:achDeH(x.name),description:achDeH(x.description),criteria:achDeH(x.criteria)}))};achPaint(el);
 // while a scan runs, badges arrive as it goes: look again every 4 s until it is done
 const m=a.scan_meta||{},busy=['pending','in_progress'].includes(m.mode)||m.status?.state==='running'||scan?.state==='running';
 clearTimeout(Pages._achT);if(busy)Pages._achT=setTimeout(()=>{if(route().page?.id==='achievements')(pageRun(el),PAGES.achievements(p,el)).catch(()=>{})},4000);
};
const achState=x=>x.state||(x.unlocked?'unlocked':'discovered');
function achBadge(x,i){const s=achState(x),col=TIER_COLORS[x.tier||x.next_tier]||'var(--muted)',sec=s==='secret';
 const tierLab=x.tier?x.tier:sec?'Hidden':x.next_tier?'Next: '+x.next_tier:x.unlocked?'Complete':'Goal';
 const foot=sec?'Progress hidden':x.unlocked?(x.next_tier?`${num(x.progress||0)} / ${num(x.next_threshold)} to ${x.next_tier}`:x.tier?'Top tier reached':'Goal complete'):x.next_tier?`${num(x.progress||0)} / ${num(x.next_threshold)} to ${x.next_tier}`:Math.round(x.progress_pct||0)+'% there';
 const ev=x.evidence;
 return `<div class="card ach ${x.unlocked?'on':''} ${sec?'secret':''}" ${st(i)}><div class="ach-top"><span class="ach-ic ${x.unlocked?'won':''}" style="--tc:${TIER_COLORS[x.tier]||'var(--muted)'}">${sec?icon('lock',18):badgeIcon(x.icon,20)}${x.unlocked||sec?'':`<i class="ach-lock">${icon('lock',10)}</i>`}</span><div style="min-width:0"><b>${esc(sec?'Secret badge':x.name)}</b><span>${esc(sec?'Hidden until you first do something that counts.':x.description||'')}</span></div></div>
  ${x.criteria?`<details class="kd-fold ach-what" data-id="${esc(x.id)}"><summary>${sec?'How to reveal it':'What counts'}</summary><div><p>${esc(x.criteria)}</p></div></details>`:''}
  ${ev&&x.unlocked?`<a class="ach-ev" href="#/chat/${encodeURIComponent(ev.session_id||'')}" title="Open the chat that earned it">${icon('chat',13)}<span>${esc(achDeH(ev.title)||'A chat')}</span></a>`:''}
  <div class="ach-bar"><i style="width:${sec?0:Math.min(100,Math.max(x.unlocked?100:3,Math.round(x.progress_pct||0)))}%;background:${x.unlocked?col:'linear-gradient(90deg,var(--blue-2),var(--blue))'}"></i></div>
  <div class="ach-foot"><span class="ach-chips"><span class="chip" ${x.tier?`style="color:${col}"`:''}>${x.tier?'<i class="dot"></i>':''}${esc(tierLab)}</span>${s!=='unlocked'?`<span class="chip">${sec?'Secret':'In progress'}</span>`:''}</span><small>${esc(foot)}</small></div>
  ${x.unlocked?`<button class="ghost small ach-share" data-act="ach-share" data-id="${esc(x.id)}">${icon('popout',14)}Share</button>`:''}</div>`}
function achPaint(el){const {a,recent,scan,list}=Pages._ach||{};if(!list)return;const open=new Set([...el.querySelectorAll('.ach-what[open]')].map(d=>d.dataset.id));const unlocked=list.filter(x=>x.unlocked),cats=[...new Set(list.map(x=>x.category||'Other'))];
 const rec=(Array.isArray(recent)?recent:recent?.unlocks||recent?.recent||[]).slice(0,6),latest=rec[0];
 const disc=a.discovered_count??list.filter(x=>achState(x)==='discovered').length,secs=a.secret_count??list.filter(x=>achState(x)==='secret').length;
 const m=a.scan_meta||{},busy=['pending','in_progress'].includes(m.mode)||m.status?.state==='running'||scan?.state==='running',done=Number(m.sessions_scanned_so_far||m.sessions_total||0),tot=Number(m.sessions_expected_total||0),pct=tot?Math.min(100,Math.floor(done/tot*100)):0;
 if(!cats.includes(ACH_F.cat))ACH_F.cat='All';
 const show=list.filter(x=>(ACH_F.cat==='All'||(x.category||'Other')===ACH_F.cat)&&(ACH_F.vis==='all'||achState(x)===ACH_F.vis));
 const pills=(k,opts)=>`<div class="ach-pills" role="group">${opts.map(([v,l])=>`<button class="${ACH_F[k]===v?'on':''}" data-act="ach-filter" data-k="${k}" data-v="${esc(v)}" aria-pressed="${ACH_F[k]===v}">${esc(l)}</button>`).join('')}</div>`;
 const rank=Object.keys(TIER_COLORS),best=unlocked.map(x=>x.tier).filter(Boolean).sort((p2,q)=>rank.indexOf(q)-rank.indexOf(p2))[0];
 el.innerHTML=`<div class="stats">${[['Unlocked',`${unlocked.length} / ${list.length}`,'badges earned'],['In progress',String(disc),'started, not earned yet'],['Secrets left',String(secs),'still hidden'],['Top tier',best||'—','your best so far'],['Latest',latest?achDeH(latest.name):'—',latest?(latest.category||'')+(latest.unlocked_at?' · '+ago(latest.unlocked_at):''):'nothing yet'],['History scan',busy?'Scanning…':scan?.snapshot_generated_at?ago(scan.snapshot_generated_at):'—','of your past chats']].map(([t,v,s],i)=>`<div class="card stat" ${st(i)}><span class="th">${t}</span><b>${esc(v)}</b><small>${esc(s)}</small></div>`).join('')}</div>
  ${busy?`<div class="card ach-scan" role="status" aria-live="polite"><b>${m.mode==='pending'?'Starting to read your history…':'Reading your history…'}</b><p class="hint">${tot?`Read ${done.toLocaleString()} of ${tot.toLocaleString()} chats (${pct}%). Badges appear as they unlock.`:'Looking through your chats, tools and models. Badges appear here as they unlock.'}</p>${tot?`<div class="ach-bar"><i style="width:${pct}%;background:linear-gradient(90deg,var(--blue-2),var(--blue))"></i></div>`:''}</div>`:''}
  <div class="ach-guide"><div class="ach-legend">${rank.map((t,i)=>`<span><i style="background:${TIER_COLORS[t]}"></i>${t}</span>${i<rank.length-1?'<em>→</em>':''}`).join('')}</div><p class="hint">Badges come from your past chats: the tools, skills, models and schedules you used. Ones you have started show as In progress. Secret ones stay hidden until you first do something that counts.</p></div>
  ${rec.length?`<div class="panel card"><h2>Recently unlocked</h2>${rec.map(r=>`<p class="hint" style="margin:4px 0">${esc(achDeH(r.name||r.achievement_id||''))} ${r.tier?'· '+esc(r.tier):''} ${r.unlocked_at?'· '+ago(r.unlocked_at):''}</p>`).join('')}</div>`:''}
  ${pills('cat',[['All','All'],...cats.map(c=>[c,c])])}${pills('vis',[['all','All'],['unlocked','Earned'],['discovered','In progress'],['secret','Secret']])}
  ${show.length?cats.filter(c=>show.some(x=>(x.category||'Other')===c)).map(c=>`<h2 class="ach-cat">${esc(c)}</h2><div class="ach-grid">${show.filter(x=>(x.category||'Other')===c).sort((x,y)=>(y.unlocked-x.unlocked)||((y.progress_pct||0)-(x.progress_pct||0))).map(achBadge).join('')}</div>`).join(''):`<div class="empty-hero" style="margin-top:12px"><span style="color:var(--ink-2)">${ACH_F.vis==='secret'?'No hidden secrets left. You have found them all.':'Nothing here with these filters.'}</span></div>`}`;achKeepOpen(el,open)}
function achKeepOpen(el,open){el.querySelectorAll('.ach-what').forEach(d=>{if(open.has(d.dataset.id))d.open=true})}
ACT['ach-filter']=a=>{ACH_F[a.dataset.k]=a.dataset.v;const el=$('#pg');if(el)achPaint(el)};
ACT['ach-rescan']=async()=>{try{await post(H,'/plugins/hermes-achievements/rescan');toast('Scanning your history…');setTimeout(reload,4000)}catch(e){fail(e)}};
// a 1200×630 picture of an earned badge to share
async function achImage(x){await document.fonts?.ready;const W=1200,Hh=630,c=document.createElement('canvas');c.width=W;c.height=Hh;const g=c.getContext('2d'),col=TIER_COLORS[x.tier]||'#4f6bff',F="'Plus Jakarta Sans',system-ui,sans-serif";
 g.fillStyle='#0b0c10';g.fillRect(0,0,W,Hh);const rg=g.createRadialGradient(300,300,40,300,300,760);rg.addColorStop(0,col+'40');rg.addColorStop(.6,col+'0d');rg.addColorStop(1,'#0b0c1000');g.fillStyle=rg;g.fillRect(0,0,W,Hh);g.strokeStyle=col+'66';g.lineWidth=2;g.strokeRect(1,1,W-2,Hh-2);
 g.beginPath();g.arc(300,315,170,0,Math.PI*2);g.fillStyle=col;g.shadowColor=col;g.shadowBlur=50;g.fill();g.shadowBlur=0;
 try{const svg=badgeIcon(x.icon,24).replace('width="24" height="24"','xmlns="http://www.w3.org/2000/svg" width="200" height="200"').replace('stroke="currentColor"','stroke="#ffffff"');const img=new Image();await new Promise((ok,no)=>{img.onload=ok;img.onerror=no;img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)});g.drawImage(img,200,215,200,200)}catch{}
 const wrap=(t,w)=>{const out=[];let line='';for(const word of String(t).split(/\s+/)){const nx=line?line+' '+word:word;if(g.measureText(nx).width>w&&line){out.push(line);line=word}else line=nx}if(line)out.push(line);return out};
 g.textBaseline='top';g.fillStyle='#8b93a7';g.font='600 24px '+F;g.fillText(String(x.category||'Achievement').toUpperCase(),540,140);
 g.fillStyle='#ffffff';g.font='700 64px '+F;let y=182;for(const l of wrap(x.name||'Achievement',600).slice(0,2)){g.fillText(l,540,y);y+=76}
 if(x.tier){g.font='700 24px '+F;const lab=x.tier.toUpperCase()+' TIER',w=g.measureText(lab).width+36;g.fillStyle=col+'26';g.strokeStyle=col;g.lineWidth=1.5;g.beginPath();g.roundRect?.(540,y+12,w,44,22);g.fill();g.stroke();g.fillStyle=col;g.textBaseline='middle';g.fillText(lab,558,y+35);g.textBaseline='top';y+=72}
 g.fillStyle='#c4c9d6';g.font='500 26px '+F;for(const l of wrap(x.description||'',600).slice(0,3)){g.fillText(l,540,y+16);y+=36}
 g.fillStyle='#ffffff';g.font='700 28px '+F;g.fillText('aqeelOS',540,540);g.fillStyle='#8b93a7';g.font='500 22px '+F;g.fillText('Earned '+(x.unlocked_at?new Date(x.unlocked_at*1000).toLocaleDateString():'today'),540,578);
 return await new Promise((ok,no)=>c.toBlob(b=>b?ok(b):no(new Error('Could not draw the picture')),'image/png'))}
ACT['ach-share']=async a=>{const x=(Pages._ach?.list||[]).find(y=>String(y.id)===a.dataset.id);if(!x)return;
 const d=drawer('Share: '+x.name,`<div class="ach-share-img"><div class="skel loading"><span class="ring"></span></div></div><p class="hint">Post on X opens a ready-made post in a new tab. Press Copy image first, then paste the picture into the post.</p><p class="err-line" id="achShErr" hidden></p>`,`<button class="ghost" data-act="close">Close</button><button id="achCp" disabled>${icon('copy',15)}Copy image</button><button id="achDl" disabled>${icon('download',15)}Download PNG</button><button class="primary" id="achX">Post on X</button>`,{size:'md'});
 let blob=null,url='';const err=m=>{const e=d.querySelector('#achShErr');e.textContent=m;e.hidden=false};
 try{blob=await achImage(x);url=URL.createObjectURL(blob);const box=d.querySelector('.ach-share-img');if(box)box.innerHTML=`<img src="${url}" alt="${esc(x.name)} badge picture">`;d.querySelector('#achCp').disabled=false;d.querySelector('#achDl').disabled=false}catch(e){err(e.message||'Could not draw the picture')}
 new MutationObserver((ms,o)=>{if(!d.isConnected){o.disconnect();if(url)URL.revokeObjectURL(url)}}).observe(document.body,{childList:true});
 d.querySelector('#achCp').onclick=async()=>{try{if(!navigator.clipboard||!window.ClipboardItem)throw new Error('This browser cannot copy pictures. Use Download PNG instead.');await navigator.clipboard.write([new ClipboardItem({'image/png':blob})]);toast('Picture copied')}catch(e){err(e.message)}};
 d.querySelector('#achDl').onclick=()=>{const l=document.createElement('a');l.href=url;l.download='aqeelos-badge-'+(x.id||'badge')+'.png';document.body.append(l);l.click();l.remove();toast('Picture saved')};
 d.querySelector('#achX').onclick=()=>window.open('https://x.com/intent/post?text='+encodeURIComponent(`Just unlocked ${x.tier?x.tier+' tier ':''}“${x.name}” in aqeelOS`),'_blank','noopener,noreferrer')};
